/* ── Audio Engine ── */
var AC = new (window.AudioContext || window.webkitAudioContext)();
function beep(f,d,t,v){t=t||'sine';v=v||.08;try{var o=AC.createOscillator(),g=AC.createGain();o.connect(g);g.connect(AC.destination);o.type=t;o.frequency.value=f;g.gain.setValueAtTime(v,AC.currentTime);g.gain.exponentialRampToValueAtTime(.001,AC.currentTime+d);o.start();o.stop(AC.currentTime+d);}catch(e){}}
function playClick(){beep(880,.07,'sine',.08);}
function playPlant(){beep(440,.14,'sine',.09);setTimeout(function(){beep(660,.1,'sine',.07);},75);}
function playZombie(){beep(140,.28,'sawtooth',.06);}
function playWin(){[523,659,784,1047].forEach(function(f,i){setTimeout(function(){beep(f,.18,'sine',.09);},i*110);});}
var MELODY=[523,659,784,880,784,659,523,440,494,523,659,784,880,1047,880,784,659,523,494,440,523,587,659,698,784,698,659,587];
function playNote(){beep(MELODY[melIdx%MELODY.length],.18,'sine',.07);beep(MELODY[melIdx%MELODY.length]*.5,.36,'triangle',.04);melIdx++;melTimer=setTimeout(playNote,260);}
function toggleMusic(){musicOn=!musicOn;var btn=document.getElementById('musicBtn');if(musicOn){btn.classList.add('on');btn.textContent='🎵 On';melIdx=0;playNote();}else{btn.classList.remove('on');btn.textContent='🎵 Music';clearTimeout(melTimer);}}

/* ── Language ── */
function toggleLang(){LANG=LANG==='en'?'es':'en';document.querySelector('.lang-nb').textContent=LANG==='en'?'🌐 ES':'🌐 EN';applyLang();buildWorldMap();if(curAlmTab)buildAlmList(curAlmTab);playClick();}
function applyLang(){document.querySelectorAll('[data-en]').forEach(function(el){var v=el.getAttribute('data-'+LANG);if(v)el.innerHTML=v;});}

/* ── Navigation ── */
function goTo(id){
  var el=document.getElementById(id);
  if(!el){console.warn('Screen not found:',id);return;}
  document.querySelectorAll('.scr').forEach(function(s){s.classList.remove('active');});
  document.querySelectorAll('.nb').forEach(function(b){b.classList.remove('on');});
  el.classList.add('active');
  var btn=document.querySelector('.nb[data-s="'+id+'"]');
  if(btn)btn.classList.add('on');
  playClick();
  if(id==='s-quiz')buildQuiz();
  if(id==='s-almanac'&&!curAlmSel)switchTab('plants');
  if(typeof setCursorMode==='function')setCursorMode('leaf');
  setTimeout(function(){animeScreenIn(id);},30);
}

