/* ── Build ZMAP ── */
var ZMAP = {};
function rebuildZMAP(){
  ZOMBIES.forEach(function(z){if(z&&z.id)ZMAP[z.id]=z;});
  PLANTS.forEach(function(p){if(p&&p.id)ZMAP[p.id]=p;});
}
rebuildZMAP();

