/* ── Quiz Functions ── */
function buildQuiz(){
  var L=LANG;
  qAns=new Array(QS.length).fill(false);
  var sc=document.getElementById('quiz-score');
  if(sc)sc.style.display='none';
  var container=document.getElementById('quiz-qs');
  if(!container)return;
  container.innerHTML='';
  QS.forEach(function(q,qi){
    var card=document.createElement('div');
    card.className='qcard';card.id='qc-'+qi;
    var numDiv=document.createElement('div');numDiv.className='q-num';
    numDiv.textContent=(L==='en'?'Question':'Pregunta')+' '+(qi+1)+'/'+QS.length;
    card.appendChild(numDiv);
    var txtDiv=document.createElement('div');txtDiv.className='q-txt';
    txtDiv.textContent=q.q[L];card.appendChild(txtDiv);
    var optsDiv=document.createElement('div');optsDiv.className='q-opts';
    q.opts[L].forEach(function(opt,oi){
      var btn=document.createElement('button');
      btn.className='q-opt';btn.textContent=opt;
      (function(qi2,oi2,ans2){btn.onclick=function(){ansQ(qi2,oi2,ans2);};})(qi,oi,q.ans);
      optsDiv.appendChild(btn);
    });
    card.appendChild(optsDiv);
    var fbDiv=document.createElement('div');fbDiv.className='q-fb';fbDiv.id='qf-'+qi;
    card.appendChild(fbDiv);
    container.appendChild(card);
  });
}

function ansQ(qi,oi,cor){
  if(qAns[qi])return;qAns[qi]=true;
  var card=document.getElementById('qc-'+qi);
  card.querySelectorAll('.q-opt').forEach(function(o,i){
    o.disabled=true;
    if(i===cor)o.classList.add('ok');
    else if(i===oi&&oi!==cor)o.classList.add('no');
  });
  var fb=document.getElementById('qf-'+qi);
  fb.className='q-fb show '+(oi===cor?'ok':'no');
  fb.textContent=(oi===cor?'✅ ':'❌ ')+QS[qi].exp[LANG];
  oi===cor?playWin():playZombie();
  if(qAns.every(function(x){return x;}))setTimeout(showScore,500);
}

function showScore(){
  var L=LANG,cor=0,total=QS.length;
  for(var i=0;i<total;i++){var c=document.getElementById('qc-'+i);if(c&&c.querySelector('.ok')&&!c.querySelector('.no'))cor++;}
  var sc=document.getElementById('quiz-score');sc.style.display='block';
  var en=['Keep studying!','Good effort!','Getting there!','Excellent!','PERFECT! PvZ Software Engineer!'];
  var es=['Sigue estudiando.','Buen esfuerzo.','Ya casi.','Excelente.','PERFECTO. Ingeniero de Software PvZ.'];
  sc.innerHTML='';
  var ttl=document.createElement('div');ttl.className='qs-title';ttl.textContent=L==='en'?'Quiz Complete!':'Quiz Completo.';sc.appendChild(ttl);
  if(cor===total){
    playWin();
    var wb=document.createElement('div');wb.style.cssText='text-align:center;margin-bottom:8px;';
    var si=document.createElement('img');
    si.src="data:image/png;base64,";
    si.style.cssText='height:clamp(75px,16vw,115px);object-fit:contain;animation:winBounce2 .6s ease-in-out infinite alternate;filter:drop-shadow(0 0 14px #FFD700);';
    var wt=document.createElement('div');wt.style.cssText='font-family:Fredoka One,cursive;font-size:clamp(.82rem,2.2vw,1.1rem);color:#FFD700;margin-top:5px;';
    wt.textContent=L==='en'?'PERFECT SCORE! You are a PvZ Software Engineer!':'PUNTUACION PERFECTA. Eres un Ingeniero de Software PvZ.';
    wb.appendChild(si);wb.appendChild(wt);sc.appendChild(wb);
  } else if(cor===0){
    playZombie();
    var lb=document.createElement('div');lb.style.cssText='text-align:center;margin-bottom:8px;';
    var br=document.createElement('div');br.style.cssText='font-size:clamp(2.8rem,7vw,4.5rem);animation:dBob 1s ease-in-out infinite;';
    br.innerHTML='&#x1F9E0;';
    var lt=document.createElement('div');lt.style.cssText='font-family:Fredoka One,cursive;font-size:clamp(.75rem,1.8vw,.95rem);color:#f87171;margin-top:5px;';
    lt.textContent=L==='en'?'The zombies got your brains! Study more!':'Los zombies se comieron tus cerebros. Estudia mas.';
    lb.appendChild(br);lb.appendChild(lt);sc.appendChild(lb);
  }
  var vl=document.createElement('div');vl.className='qs-val';vl.textContent=cor+'/'+total;sc.appendChild(vl);
  var mg=document.createElement('div');mg.className='qs-msg';mg.textContent=L==='en'?en[Math.min(Math.floor(cor/total*5),4)]:es[Math.min(Math.floor(cor/total*5),4)];sc.appendChild(mg);
  sc.scrollIntoView({behavior:'smooth'});
}

/* ── Sun System ── */
function collectSun(el){
  sunVal+=25;var sv=document.getElementById('sun-val');if(sv)sv.textContent=sunVal;
  playPlant();el.style.transition='transform .15s';el.style.transform='scale(1.6)';
  setTimeout(function(){el.style.transform='scale(1)';},200);
}
function spawnSun(){
  var c=document.getElementById('sun-drops');if(!c)return;
  var el=document.createElement('div');el.className='sun-drop';
  el.style.cssText='left:'+(10+Math.random()*75)+'%;animation-duration:'+(5+Math.random()*4)+'s;';
  el.innerHTML='<span>☀️</span>';
  el.onclick=function(){sunVal+=25;var sv=document.getElementById('sun-val');if(sv)sv.textContent=sunVal;el.style.opacity='0';setTimeout(function(){if(el.parentNode)el.remove();},200);playPlant();};
  c.appendChild(el);setTimeout(function(){if(el.parentNode)el.remove();},11000);
}

/* ── AutoPlay ── */
var AP=[
  function(){goTo('s-menu');},function(){goTo('s-map');},
  function(){openWorld('day');},function(){openWorld('night');},
  function(){openWorld('pool');},function(){openWorld('fog');},function(){openWorld('roof');},
  function(){goTo('s-almanac');switchTab('plants');selectAlm('sunflower','plants');},
  function(){selectAlm('peashooter','plants');},function(){selectAlm('wallnut','plants');},
  function(){switchTab('zombies');selectAlm('z_basic','zombies');},
  function(){selectAlm('z_newspaper','zombies');},function(){selectAlm('z_bucket','zombies');},
  function(){selectAlm('gargantuar','zombies');},
  function(){goTo('s-boss');},function(){goTo('s-victory');},function(){goTo('s-quiz');}
];
function toggleAP(){apOn=!apOn;var btn=document.getElementById('apbtn');btn.className='nbx ap-nb'+(apOn?' on':'');btn.textContent=apOn?'⏹ Stop':'▶ Auto';if(apOn){apIdx=0;runAP();}else clearTimeout(apTimer);}
function runAP(){if(!apOn)return;AP[apIdx%AP.length]();apIdx++;apTimer=setTimeout(runAP,6000);}

/* ── Fullscreen ── */
function toggleFS(){if(!document.fullscreenElement){document.documentElement.requestFullscreen().catch(function(){});document.querySelector('.fs-nb').textContent='✕FS';}else{document.exitFullscreen();document.querySelector('.fs-nb').textContent='⛶';}}

/* ── Keyboard ── */
document.addEventListener('keydown',function(e){
  var map={'1':'s-menu','2':'s-map','3':'s-almanac','4':'s-boss','5':'s-victory','6':'s-quiz'};
  if(map[e.key]){goTo(map[e.key]);return;}
  if(e.key==='Escape'&&_almModalOpen){closeAlmModal({target:document.getElementById('alm-modal-overlay')});return;}
  if(e.key==='ArrowRight'||e.key==='ArrowLeft'){
    var order=['s-menu','s-map','s-almanac','s-boss','s-victory','s-quiz'];
    var cur=order.findIndex(function(s){var el=document.getElementById(s);return el&&el.classList.contains('active');});
    if(cur===-1)return;
    goTo(order[(e.key==='ArrowRight'?cur+1:cur-1+order.length)%order.length]);
  }
});

/* ── Custom Cursor ── */
(function(){
  var leaf=document.getElementById('cursor-leaf');
  var brain=document.getElementById('cursor-brain');
  var trail=document.getElementById('cursor-trail');
  if(!leaf)return;
  var brainMode=false;
  document.addEventListener('mousemove',function(e){
    var mx=e.clientX,my=e.clientY;
    var cur=brainMode?brain:leaf,hid=brainMode?leaf:brain;
    cur.style.left=mx+'px';cur.style.top=my+'px';cur.style.display='flex';hid.style.display='none';
    setTimeout(function(){trail.style.left=mx+'px';trail.style.top=my+'px';},80);
  });
  document.addEventListener('mousedown',function(){var cur=brainMode?brain:leaf;cur.classList.remove('cursor-clicking');void cur.offsetWidth;cur.classList.add('cursor-clicking');});
  window.setCursorMode=function(mode){brainMode=(mode==='brain');trail.className=brainMode?'brain-mode':'';};
  document.addEventListener('mouseleave',function(){leaf.style.display='none';brain.style.display='none';trail.style.opacity='0';});
  document.addEventListener('mouseenter',function(){trail.style.opacity='1';});
})();

/* ── Anime.js Screen Animations ── */
function animeScreenIn(id){
  if(typeof anime==='undefined')return;
  var el=document.getElementById(id);if(!el)return;
  var targets=el.querySelectorAll('.panel,.vcard,.bcard,.qcard,.wnode,.alm-item,.pd-card,.zd-card,.gcard,.how-to,.tl-item,.uitem,.sw-card,.special-card');
  if(!targets.length)return;
  anime({targets:targets,opacity:[0,1],translateY:[16,0],scale:[0.97,1],duration:380,delay:anime.stagger(48),easing:'easeOutQuad'});
}

/* ── Intro ── */
function runIntro(){
  var msgs={en:['Loading the garden...','Waking up Crazy Dave...','Spawning zombie horde...','Initializing defense grid...','Ready!'],
            es:['Cargando el jardín...','Despertando a Crazy Dave...','Generando horda zombie...','Inicializando cuadrícula...','¡Listo!']};
  var bar=document.getElementById('lbar'),txt=document.getElementById('ltext'),s=0;
  var iv=setInterval(function(){
    s++;if(bar)bar.style.width=(s/5*100)+'%';if(txt)txt.textContent=msgs[LANG][Math.min(s-1,4)];
    beep(180+s*65,.09,'square',.05);
    if(s>=5){clearInterval(iv);setTimeout(function(){
      var intro=document.getElementById('intro');
      if(intro){intro.classList.add('out');setTimeout(function(){if(intro.parentNode)intro.remove();},1000);}
      playWin();
    },500);}
  },480);
}

/* ── Init ── */
document.addEventListener('DOMContentLoaded',function(){
  buildWorldMap();applyLang();switchTab('plants');
  for(var i=0;i<3;i++){(function(j){setTimeout(spawnSun,j*2200);})(i);}
  setInterval(spawnSun,4500);
  runIntro();
});
